mapper.select:
SELECT

FROM travel_plan_polls p
         LEFT JOIN travel_plan_members m ON m.id = p.created_by_member_id
WHERE p.travel_plan_id = #{travelPlanId}

ORDER BY p.id DESC
LIMIT #{limit}

SELECT

FROM travel_plan_polls p
         LEFT JOIN travel_plan_members m ON m.id = p.created_by_member_id
WHERE p.travel_plan_id = #{travelPlanId}
  AND p.id < #{beforePollId}

ORDER BY p.id DESC
LIMIT #{limit}

SELECT

FROM travel_plan_polls p
         LEFT JOIN travel_plan_members m ON m.id = p.created_by_member_id
WHERE p.id = #{id}
  AND p.travel_plan_id = #{travelPlanId}

SELECT id, poll_id, content, display_order, created_at, updated_at FROM travel_plan_poll_options WHERE poll_id IN
#{pollId}
ORDER BY poll_id ASC, display_order ASC, id ASC

SELECT COUNT(*)
FROM travel_plan_poll_options
WHERE poll_id = #{pollId}

SELECT COUNT(*)
FROM travel_plan_poll_options
WHERE poll_id = #{pollId}
  AND id IN

    #{optionId}

SELECT id, poll_id, member_id, created_at, updated_at
FROM travel_plan_poll_votes
WHERE poll_id = #{pollId}
  AND member_id = #{memberId}

SELECT v.poll_id AS poll_id, COUNT(*) AS voted_member_count FROM travel_plan_poll_votes v JOIN travel_plan_members m ON m.id = v.member_id WHERE v.poll_id IN
#{pollId}
AND m.status = 'ACTIVE' GROUP BY v.poll_id

SELECT v.poll_id AS poll_id, s.option_id AS option_id, COUNT(*) AS vote_count FROM travel_plan_poll_vote_selections s JOIN travel_plan_poll_votes v ON v.id = s.vote_id JOIN travel_plan_members m ON m.id = v.member_id WHERE v.poll_id IN
#{pollId}
AND m.status = 'ACTIVE' GROUP BY v.poll_id, s.option_id

mapper.delete:
DELETE FROM travel_plan_polls
WHERE id = #{id}
  AND travel_plan_id = #{travelPlanId}

DELETE v
FROM travel_plan_poll_votes v
         JOIN travel_plan_polls p ON p.id = v.poll_id
WHERE p.travel_plan_id = #{travelPlanId}
  AND p.status = 'OPEN'
  AND v.member_id = #{memberId}
